const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shanghai = ee.Geometry.Point(121.4737, 31.2304); // Approximate center of Shanghai
  const startDate = '2013-08-07';
  const endDate = '2013-08-08'; // End date is exclusive

  // 2. Data Acquisition
  // Use MODIS/051/MOD11A1 for daily Land Surface Temperature (LST)
  let lstCollection = ee.ImageCollection('MODIS/051/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(shanghai);

  // Check if collection is empty
  let collectionSize = await lstCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No MODIS MOD11A1 images found for August 7, 2013, in Shanghai.");
    console.log("C1");
    return;
  }

  // 3. Processing
  // Select the LST_Day_1km band and the QC_Day band
  // Apply scaling factor (0.02) and convert from Kelvin to Celsius
  // Filter for good quality pixels (QC_Day bits 0-1 are '00') and clear sky (QC_Day bits 2-3 are '00')
  const processLST = function(image) {
    const lstDay = image.select('LST_Day_1km').multiply(0.02); // Scale to Kelvin
    const lstCelsius = lstDay.subtract(273.15); // Convert to Celsius

    // Quality Control (QC_Day band)
    // Bits 0-1: LST quality. 00 = good quality
    // Bits 2-3: Cloud contamination. 00 = not used, 01 = cloudy, 10 = mixed cloud, 11 = not used.
    // We want good quality (00) and clear sky (00).
    const qc = image.select('QC_Day');
    const lstQuality = qc.rightShift(0).mod(4); // Extract bits 0-1
    const cloudContam = qc.rightShift(2).mod(4); // Extract bits 2-3

    // Mask for good quality LST and clear sky conditions
    const goodQualityMask = lstQuality.eq(0); // LST quality is good
    const clearSkyMask = cloudContam.eq(0);   // Not cloudy

    const validPixelsMask = goodQualityMask.and(clearSkyMask);

    return lstCelsius.updateMask(validPixelsMask).rename('LST_Celsius');
  };

  let processedLST = lstCollection.map(processLST);

  // Take the first (and likely only) image for the day
  let image = processedLST.first();

  // If after processing, the image is null or no bands, it's an issue
  if (image === null) {
     console.log("No valid image after processing for August 7, 2013, in Shanghai.");
     console.log("C1"); // Or C3, depending on where the null originates. If it's `first()` being null, then C1.
     return;
  }

  // Calculate pixel count to detect C2
  const pixelCount = await image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: shanghai,
    scale: 1000, // MODIS resolution is 1km
    maxPixels: 1e9
  }).get('LST_Celsius').getInfo();

  if (pixelCount === 0 || pixelCount === null) {
    console.log("No valid pixels remain after quality masking for August 7, 2013, in Shanghai.");
    console.log("C2");
    return;
  }

  // 4. Calculation
  const meanLST = await image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: shanghai,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Celsius').getInfo();

  // 5. Validation & Final Answer
  if (meanLST === null || isNaN(meanLST)) {
    console.log("Calculated mean LST is null or NaN.");
    console.log("C3");
  } else {
    console.log(`Mean LST in Shanghai on 2013-08-07: ${meanLST.toFixed(2)} °C`);
    console.log(`Valid Pixels: ${pixelCount}`);
    if (meanLST > 39) {
      console.log("A");
    } else {
      console.log("B");
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
